function dist(a: Point, b: Point): number {
  return Math.hypot(a[0] - b[0], a[1] - b[1])
}

function concat(a: Point[], b: Point[]): Point[] {
  const out = a.slice()
  const start = dist(out[out.length - 1]!, b[0]!) < 1e-4 ? 1 : 0
  for (let i = start; i < b.length; i++)
    out.push(b[i]!)
  return out
}

function orient(pts: Point[], reverse: boolean): Point[] {
  return reverse ? pts.slice().reverse() : pts.slice()
}

/** Join sequential subpaths of one glyph when their endpoints meet. */
function joinSubpaths(strokes: Point[][], tol: number): Point[][] {
  const out = strokes.map(s => s.slice())
  let i = 0
  while (i < out.length - 1) {
    const a = out[i]!
    const b = out[i + 1]!
    const opts: [number, boolean, boolean][] = [
      [dist(a[a.length - 1]!, b[0]!), false, false],
      [dist(a[a.length - 1]!, b[b.length - 1]!), false, true],
      [dist(a[0]!, b[0]!), true, false],
      [dist(a[0]!, b[b.length - 1]!), true, true],
    ]
    opts.sort((p, q) => p[0] - q[0])
    const best = opts[0]!
    if (best[0] > tol) {
      i++
      continue
    }
    const ra = best[1]
    const rb = best[2]
    out.splice(i, 2, concat(orient(a, ra), orient(b, rb)))
  }
  return out
}

interface Run {
  pts: Point[]
  owner: number
}

interface Merge {
  d: number
  pi: number
  ni: number
  rp: boolean
  rn: boolean
}

function mergeAcross(strokes: Run[], prevOwner: number, placed: Point[][], owner: number, tol: number): Run[] {
  const prevIdx: number[] = []
  for (let i = 0; i < strokes.length; i++) {
    if (strokes[i]!.owner === prevOwner)
      prevIdx.push(i)
  }
  const cands: Merge[] = []
  for (const pi of prevIdx) {
    const P = strokes[pi]!.pts
    for (let ni = 0; ni < placed.length; ni++) {
      const N = placed[ni]!
      const opts: [number, boolean, boolean][] = [
        [dist(P[P.length - 1]!, N[0]!), false, false],
        [dist(P[P.length - 1]!, N[N.length - 1]!), false, true],
        [dist(P[0]!, N[0]!), true, false],
        [dist(P[0]!, N[N.length - 1]!), true, true],
      ]
      for (const [d, rp, rn] of opts) {
        if (d <= tol)
          cands.push({ d, pi, ni, rp, rn })
      }
    }
  }
  cands.sort((a, b) => a.d - b.d)
  const usedP = new Set<number>()
  const usedN = new Set<number>()
  const merges: Merge[] = []
  for (const c of cands) {
    if (usedP.has(c.pi) || usedN.has(c.ni))
      continue
    usedP.add(c.pi)
    usedN.add(c.ni)
    merges.push(c)
  }
  const byPrev = new Map<number, Point[]>()
  for (const m of merges)
    byPrev.set(m.pi, concat(orient(strokes[m.pi]!.pts, m.rp), orient(placed[m.ni]!, m.rn)))
  const out: Run[] = []
  for (let i = 0; i < strokes.length; i++) {
    const merged = byPrev.get(i)
    if (merged)
      out.push({ pts: merged, owner })
    else
      out.push(strokes[i]!)
  }
  for (let ni = 0; ni < placed.length; ni++) {
    if (!usedN.has(ni))
      out.push({ pts: placed[ni]!, owner })
  }
  return out
}

function resample(pts: Point[], step: number): Point[] {
  const first = pts[0]
  if (!first)
    return []
  if (pts.length === 1)
    return [[first[0], first[1]]]
  const out: Point[] = [[first[0], first[1]]]
  let carry = 0
  for (let i = 1; i < pts.length; i++) {
    const prev = pts[i - 1]!
    const next = pts[i]!
    const x0 = prev[0]
    const y0 = prev[1]
    const x1 = next[0]
    const y1 = next[1]
    const seg = Math.hypot(x1 - x0, y1 - y0)
    if (seg === 0)
      continue
    let walked = 0
    while (carry + (seg - walked) >= step) {
      const need = step - carry
      walked += need
      const t = walked / seg
      out.push([x0 + (x1 - x0) * t, y0 + (y1 - y0) * t])
      carry = 0
    }
    carry += seg - walked
  }
  const end = pts[pts.length - 1]!
  const last = out[out.length - 1]!
  if (Math.hypot(end[0] - last[0], end[1] - last[1]) > 1e-4)
    out.push([end[0], end[1]])
  return out
}

export function layoutText(text: string, { size = 100, tracking = 0 }: { size?: number, tracking?: number } = {}): GlyphLayout {
  const tol = 0.06 * size
  const step = size / 60
  let pen = 0
  let owner = 0
  let prevOwner = -1
  let runs: Run[] = []
  const chars = [...text]
  for (let i = 0; i < chars.length; i++) {
    const g = G[chars[i] ?? '']
    const adv = g ? g[0] : SPACE
    const raw = g
      ? g.slice(1).flatMap((stroke) => {
          if (!isStroke(stroke))
            return []
          return [stroke.map(([x, y]): Point => [x * size + pen, y * size])]
        })
      : []
    const placed = joinSubpaths(raw, tol)
    if (placed.length && prevOwner >= 0) {
      runs = mergeAcross(runs, prevOwner, placed, owner, tol)
    }
    else {
      for (const pts of placed) runs.push({ pts, owner })
    }
    prevOwner = placed.length ? owner : -1
    owner++
    pen += adv * size
    if (i < chars.length - 1)
      pen += tracking
  }
  const strokes: Point[][] = []
  for (const run of runs) {
    const pts = resample(run.pts, step)
    if (pts.length > 1)
      strokes.push(pts)
  }
  return { strokes, width: pen, ascent: ASCENT * size, descent: DESCENT * size }
}

function unitTangent(pts: Point[], atEnd: boolean, size: number): Point {
  const first = pts[0]
  if (pts.length < 2 || !first)
    return [1, 0]
  const minD = size / 30
  const anchor = atEnd ? pts[pts.length - 1]! : first
  let i = atEnd ? pts.length - 2 : 1
  const step = atEnd ? -1 : 1
  const stop = atEnd ? 0 : pts.length - 1
  while (i !== stop && dist(pts[i]!, anchor) < minD)
    i += step
  const p = pts[i]!
  const dx = atEnd ? anchor[0] - p[0] : p[0] - anchor[0]
  const dy = atEnd ? anchor[1] - p[1] : p[1] - anchor[1]
  const L = Math.hypot(dx, dy)
  if (L < 1e-6)
    return [1, 0]
  return [dx / L, dy / L]
}

function flattenCubicPx(p0: Point, p1: Point, p2: Point, p3: Point, step: number): Point[] {
  const pts: Point[] = [[p0[0], p0[1]]]
  const mid = (p: Point, q: Point): Point => [(p[0] + q[0]) / 2, (p[1] + q[1]) / 2]
  const rec = (a: Point, b: Point, c: Point, d: Point, depth: number): void => {
    const chord = dist(a, d)
    const poly = dist(a, b) + dist(b, c) + dist(c, d)
    if (depth > 16 || (chord <= step && poly - chord <= step * 0.35)) {
      pts.push([d[0], d[1]])
      return
    }
    const ab = mid(a, b)
    const bc = mid(b, c)
    const cd = mid(c, d)
    const abc = mid(ab, bc)
    const bcd = mid(bc, cd)
    const m = mid(abc, bcd)
    rec(a, ab, abc, m, depth + 1)
    rec(m, bcd, cd, d, depth + 1)
  }
  rec(p0, p1, p2, p3, 0)
  return resample(pts, step)
}

export function joinStrokes(strokes: Point[][], { size = 100 }: { size?: number } = {}): Point[] {
  const runs: Point[][] = []
  for (const s of strokes) {
    if (s && s.length)
      runs.push(s)
  }
  const first = runs[0]
  if (!first)
    return []
  const step = size / 60
  const out: Point[] = first.map(p => [p[0], p[1]])
  for (let k = 0; k < runs.length - 1; k++) {
    const a = runs[k]!
    const b = runs[k + 1]!
    const p0 = a[a.length - 1]!
    const p1 = b[0]!
    const gap = dist(p0, p1)
    if (gap < 1e-3) {
      for (let i = 1; i < b.length; i++)
        out.push([b[i]![0], b[i]![1]])
      continue
    }
    const t0 = unitTangent(a, true, size)
    const t1 = unitTangent(b, false, size)
    const m = 0.6 * gap
    const c1: Point = [p0[0] + (t0[0] * m) / 3, p0[1] + (t0[1] * m) / 3]
    const c2: Point = [p1[0] - (t1[0] * m) / 3, p1[1] - (t1[1] * m) / 3]
    const bridge = flattenCubicPx(p0, c1, c2, p1, step)
    for (let i = 1; i < bridge.length; i++)
      out.push(bridge[i]!)
    for (let i = 1; i < b.length; i++)
      out.push([b[i]![0], b[i]![1]])
  }
  return out
}
